const ALLOWED_EMAIL = 'pfgutierrez@fpconstruccion.es';

function doGet() {
  return json_({
    ok: true,
    service: 'Google Classroom Apps Script Bridge',
    version: '0.1.0'
  });
}

function doPost(e) {
  try {
    const body = JSON.parse((e && e.postData && e.postData.contents) || '{}');
    assertSecret_(body.secret);
    assertOwner_();

    const action = String(body.action || '');
    const p = body.payload || {};

    let result;
    switch (action) {
      case 'health':
        result = { ok: true, email: ALLOWED_EMAIL };
        break;
      case 'list_courses':
        result = listCourses_();
        break;
      case 'list_topics':
        result = listTopics_(p.courseId);
        break;
      case 'create_topic':
        result = createTopic_(p.courseId, p.name);
        break;
      case 'list_coursework':
        result = listCourseWork_(p.courseId);
        break;
      case 'create_assignment':
        result = createAssignment_(p.courseId, p);
        break;
      case 'create_material':
        result = createMaterial_(p.courseId, p);
        break;
      case 'create_announcement':
        result = createAnnouncement_(p.courseId, p);
        break;
      case 'list_submissions':
        result = listSubmissions_(p.courseId);
        break;
      default:
        throw new Error('Acción no reconocida: ' + action);
    }

    return json_({ ok: true, result: result });
  } catch (err) {
    return json_({
      ok: false,
      error: String(err && err.message ? err.message : err)
    });
  }
}

function assertSecret_(provided) {
  const expected = PropertiesService.getScriptProperties().getProperty('SHARED_SECRET');
  if (!expected) throw new Error('SHARED_SECRET no está configurado en Propiedades del script');
  if (String(provided || '') !== expected) throw new Error('No autorizado');
}

function assertOwner_() {
  const effective = String(Session.getEffectiveUser().getEmail() || '').toLowerCase();
  if (effective && effective !== ALLOWED_EMAIL.toLowerCase()) {
    throw new Error('Cuenta efectiva no autorizada: ' + effective);
  }
}

function assertCourse_(courseId) {
  if (!courseId) throw new Error('courseId es obligatorio');
  const allowed = PropertiesService.getScriptProperties().getProperty('ALLOWED_COURSE_ID');
  if (allowed && String(courseId) !== String(allowed)) {
    throw new Error('Curso no autorizado: ' + courseId);
  }
}

function listCourses_() {
  let courses = [];
  let pageToken;
  do {
    const opt = {
      teacherId: 'me',
      courseStates: ['ACTIVE'],
      pageSize: 100
    };
    if (pageToken) opt.pageToken = pageToken;
    const r = Classroom.Courses.list(opt);
    courses = courses.concat(r.courses || []);
    pageToken = r.nextPageToken;
  } while (pageToken);

  const allowed = PropertiesService.getScriptProperties().getProperty('ALLOWED_COURSE_ID');
  if (allowed) courses = courses.filter(c => String(c.id) === String(allowed));

  return courses.map(c => ({
    id: c.id,
    name: c.name,
    section: c.section || '',
    courseState: c.courseState,
    alternateLink: c.alternateLink || ''
  }));
}

function listTopics_(courseId) {
  assertCourse_(courseId);
  const r = Classroom.Courses.Topics.list(courseId, { pageSize: 100 });
  return r.topic || [];
}

function createTopic_(courseId, name) {
  assertCourse_(courseId);
  if (!name) throw new Error('name es obligatorio');
  return Classroom.Courses.Topics.create({ name: String(name) }, courseId);
}

function listCourseWork_(courseId) {
  assertCourse_(courseId);
  const r = Classroom.Courses.CourseWork.list(courseId, { pageSize: 100 });
  return r.courseWork || [];
}

function linkMaterials_(links) {
  if (!Array.isArray(links)) return [];
  return links.map(x => ({
    link: {
      url: String(x.url),
      title: x.title ? String(x.title) : undefined
    }
  }));
}

function createAssignment_(courseId, p) {
  assertCourse_(courseId);
  const work = {
    title: String(p.title || ''),
    description: p.description ? String(p.description) : '',
    workType: 'ASSIGNMENT',
    state: p.state || 'DRAFT',
    materials: linkMaterials_(p.links)
  };

  if (!work.title) throw new Error('title es obligatorio');
  if (p.topicId) work.topicId = String(p.topicId);
  if (p.maxPoints !== undefined && p.maxPoints !== null) work.maxPoints = Number(p.maxPoints);
  if (p.dueDate) work.dueDate = p.dueDate;
  if (p.dueTime) work.dueTime = p.dueTime;
  if (p.scheduledTime) work.scheduledTime = String(p.scheduledTime);

  return Classroom.Courses.CourseWork.create(work, courseId);
}

function createMaterial_(courseId, p) {
  assertCourse_(courseId);
  const material = {
    title: String(p.title || ''),
    description: p.description ? String(p.description) : '',
    state: p.state || 'DRAFT',
    materials: linkMaterials_(p.links)
  };

  if (!material.title) throw new Error('title es obligatorio');
  if (p.topicId) material.topicId = String(p.topicId);
  if (p.scheduledTime) material.scheduledTime = String(p.scheduledTime);

  return Classroom.Courses.CourseWorkMaterials.create(material, courseId);
}

function createAnnouncement_(courseId, p) {
  assertCourse_(courseId);
  const announcement = {
    text: String(p.text || ''),
    state: p.state || 'DRAFT',
    materials: linkMaterials_(p.links)
  };

  if (!announcement.text) throw new Error('text es obligatorio');
  if (p.scheduledTime) announcement.scheduledTime = String(p.scheduledTime);

  return Classroom.Courses.Announcements.create(announcement, courseId);
}

function listSubmissions_(courseId) {
  assertCourse_(courseId);
  const r = Classroom.Courses.CourseWork.StudentSubmissions.list(courseId, '-', { pageSize: 100 });
  return r.studentSubmissions || [];
}

function json_(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}
